# Generated by GPT-6.2 Astra
import argparse
from pathlib import Path

import numpy as np

from character_data import read_records
from character_model import MODEL56, ROOT, layers, write_mem
from character_twin import input_pixels


def export_all(cases, model, out):
    out.mkdir(parents=True, exist_ok=True)
    write_mem(out / "npu_input.mem", np.stack(cases).ravel(), 16)
    computed = [layers(frame, model) for frame in cases]
    for i, name in enumerate(("c0", "p0", "c1", "p1", "c2", "p2", "c3", "scores")):
        a = np.stack([v[i] for v in computed])
        if name == "scores":
            a = a.ravel()
        else:
            a = a.transpose(0, 2, 3, 1).reshape(-1, a.shape[1])
        write_mem(out / (name + ".mem"), a, 32 if name == "scores" else 8)


def write_vectors(out, model_dir=MODEL56, *, quick=False):
    with np.load(model_dir / "integer_model.npz") as archive:
        model = dict(archive)
    refs = sorted(
        (r for r in read_records() if r["kind"] == "reference"),
        key=lambda r: r["class_id"],
    )
    if quick:
        export_all([input_pixels(refs[0]["file"], "card", 56)], model, out)
        return
    cases = [input_pixels(r["file"], "card", 56) for r in refs]
    cases.extend(np.full((56, 56), n, np.uint16) for n in (65535, 63488, 2016, 31))
    cases.append(np.arange(3136, dtype=np.uint16).reshape(56, 56) * np.uint16(83))
    export_all(cases, model, out)


def main():
    parser = argparse.ArgumentParser(
        description="Integer reference vectors for every displayed case and every pass through the shared core."
    )
    parser.add_argument("--out", type=Path, default=ROOT / "build" / "vectors56")
    args = parser.parse_args()
    write_vectors(args.out)


if __name__ == "__main__":
    main()
